<?php

declare(strict_types=1);

namespace Windwalker\Database\Test\Manager\Oracle;

use Windwalker\Database\Platform\DbPlatform;
use Windwalker\Database\Test\Manager\AbstractWriterManagerTestCase;

class OracleWriterManagerCrudTest extends AbstractWriterManagerTestCase
{
    protected static DbPlatform $platform = DbPlatform::Oracle;

    protected static string $driver = 'pdo_oci';

    protected static function createWriterTable(): void
    {
        self::dropOracleTable('WRITER_ITEMS');
        self::$baseConn->exec(
            'CREATE TABLE writer_items (id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, '
            . 'title VARCHAR2(255) DEFAULT \' \' NOT NULL UNIQUE, state NUMBER(10) DEFAULT 0 NULL, params VARCHAR2(4000) NULL)'
        );
    }

    protected static function resetWriterTableData(): void
    {
        // TRUNCATE does not restart identity columns, so recreate the table.
        static::createWriterTable();
    }

    protected static function dropOracleTable(string $table): void
    {
        self::$baseConn->exec(
            "BEGIN EXECUTE IMMEDIATE 'DROP TABLE $table CASCADE CONSTRAINTS PURGE'; "
            . 'EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF; END;'
        );
    }
}
